import sympy

def main():
    # Given values
    r = 5          # resistance of each resistor, Ω
    R_target = 3   # target total resistance, Ω

    # Target ratio (as a multiple of r)
    target_ratio = sympy.Rational(R_target, r)  # 3/5

    # Dynamic programming to generate all achievable resistance ratios
    # using n identical resistors in series-parallel networks.
    S = {1: {sympy.Rational(1, 1)}}
    max_n = 10
    found_n = None

    for n in range(2, max_n + 1):
        S[n] = set()
        for i in range(1, n):
            j = n - i
            for a in S[i]:
                for b in S[j]:
                    # Series combination
                    S[n].add(a + b)
                    # Parallel combination (product / sum)
                    if a + b != 0:
                        S[n].add((a * b) / (a + b))
        if target_ratio in S[n]:
            found_n = n
            break

    if found_n is not None:
        print(f"FINAL ANSWER: {found_n}")
        print("UNIT: resistors")
    else:
        # If not found within max_n, increase max_n or report error
        print("FINAL ANSWER: not found")
        print("UNIT: resistors")

if __name__ == "__main__":
    main()
